	mut var_settings := { 'enabled': { 'title': rt.call_function('__', [rt.new_string('Enable/Disable'), rt.new_string('woocommerce')]), 'type': rt.new_string('checkbox'), 'label': rt.call_function('__', [rt.new_string('Once disabled, this legacy method will no longer be available.'), rt.new_string('woocommerce')]), 'default': rt.new_string('no') }, 'title': { 'title': rt.call_function('__', [rt.new_string('Method title'), rt.new_string('woocommerce')]), 'type': rt.new_string('text'), 'description': rt.call_function('__', [rt.new_string('This controls the title which the user sees during checkout.'), rt.new_string('woocommerce')]), 'default': rt.call_function('__', [rt.new_string('Flat rate'), rt.new_string('woocommerce')]), 'desc_tip': rt.new_bool(true) }, 'availability': { 'title': rt.call_function('__', [rt.new_string('Availability'), rt.new_string('woocommerce')]), 'type': rt.new_string('select'), 'default': rt.new_string('all'), 'class': rt.new_string('availability wc-enhanced-select'), 'options': { 'all': rt.call_function('__', [rt.new_string('All allowed countries'), rt.new_string('woocommerce')]), 'specific': rt.call_function('__', [rt.new_string('Specific Countries'), rt.new_string('woocommerce')]) } }, 'countries': { 'title': rt.call_function('__', [rt.new_string('Specific countries'), rt.new_string('woocommerce')]), 'type': rt.new_string('multiselect'), 'class': rt.new_string('wc-enhanced-select'), 'css': rt.new_string('width: 400px;'), 'default': rt.new_string(''), 'options': rt.call_method(rt.get_property(rt.call_function('WC', []rt.PhpVal{}), 'countries'), 'get_shipping_countries', []rt.PhpVal{}), 'custom_attributes': { 'data-placeholder': rt.call_function('__', [rt.new_string('Select some countries'), rt.new_string('woocommerce')]) } }, 'tax_status': { 'title': rt.call_function('__', [rt.new_string('Tax status'), rt.new_string('woocommerce')]), 'type': rt.new_string('select'), 'class': rt.new_string('wc-enhanced-select'), 'default': Class_Automattic_WooCommerce_Enums_ProductTaxStatus.taxable(), 'options': { Class_Automattic_WooCommerce_Enums_ProductTaxStatus.taxable(): rt.call_function('__', [rt.new_string('Taxable'), rt.new_string('woocommerce')]), Class_Automattic_WooCommerce_Enums_ProductTaxStatus.none(): rt.call_function('_x', [rt.new_string('None'), rt.new_string('Tax status'), rt.new_string('woocommerce')]) } }, 'cost': { 'title': rt.call_function('__', [rt.new_string('Cost'), rt.new_string('woocommerce')]), 'type': rt.new_string('text'), 'placeholder': rt.new_string(''), 'description': var_cost_desc, 'default': rt.new_string(''), 'desc_tip': rt.new_bool(true) } }
