	}
	if rt.is_true(rt.call_function('apply_filters', [rt.new_string('woocommerce_enable_deprecated_additional_flat_rates'), rt.call_method(rt.new_object('', []string{}, &this), 'get_option', [rt.new_string('options'), rt.new_bool(false)])])) {
