		var_settings['options'] = rt.create_array([rt.ArrayItem{ key: 'title', val: rt.call_function('__', [rt.new_string('Additional rates'), rt.new_string('woocommerce')]) }, rt.ArrayItem{ key: 'type', val: 'textarea' }, rt.ArrayItem{ key: 'description', val: rt.call_function('__', [rt.new_string('One per line: Option name | Additional cost [+- Percents] | Per cost type (order, class, or item) Example: <code>Priority mail | 6.95 [+ 0.2%] | order</code>.'), rt.new_string('woocommerce')]) }, rt.ArrayItem{ key: 'default', val: '' }, rt.ArrayItem{ key: 'desc_tip', val: true }, rt.ArrayItem{ key: 'placeholder', val: rt.call_function('__', [rt.new_string('Option name | Additional cost [+- Percents%] | Per cost type (order, class, or item)'), rt.new_string('woocommerce')]) }])
